ValidationRule.errorConditionFormula:
AND(
TEXT(PRIORVALUE(Status)) = "Eligible",

/* Only validate when the value is actually changing */
TEXT(Status) <> TEXT(PRIORVALUE(Status)),

NOT(
OR(
/* Pre-Lottery allowed transitions from Eligible */
AND(NOT(Has_Lottery_Run__c), ISPICKVAL(Status, "Pre-Offer")),
AND(NOT(Has_Lottery_Run__c), ISPICKVAL(Status, "Submitted")),
AND(NOT(Has_Lottery_Run__c), ISPICKVAL(Status, "Withdrawn/Declined")),

/* Post-Lottery allowed transition from Eligible */
AND(Has_Lottery_Run__c, ISPICKVAL(Status, "Waitlisted")),
AND(NOT(Has_Lottery_Run__c), ISPICKVAL(Status, "Withdrawn/Declined"))
)
)
)
